'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {createHash} = require('node:crypto');
const {avatar} = require('../avatar.cjs');
const {setup, register, auth} = require('./helpers.cjs');
// Synthetic 2x2 RGBA PNGs generated by Pillow, independently of the validator.
const image = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAFElEQVR4nGP838Dwn4GBgYGJAQoAJxcCgnGUo04AAAAASUVORK5CYII=';
const withText = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAFHRFWHRub3RlAHByaXZhdGUgY29udGVudOV2f9AAAAAUSURBVHicY/zfwPCfgYGBgYkBCgAnFwKCcZSjTgAAAABJRU5ErkJggg==';

test('PNG avatars accept real RGBA thumbnail bytes and reject metadata, corrupt CRC and trailing payload', () => {
  const bytes = Buffer.from(image.split(',')[1], 'base64');
  assert.equal(avatar(image).avatarHash, createHash('sha256').update(bytes).digest('hex'));
  assert.deepEqual(avatar(null), {avatar: null, avatarHash: null});
  assert.throws(() => avatar(withText), error => error.code === 'AVATAR_INVALID');
  const changed = Buffer.from(bytes); changed[48] ^= 1;
  assert.throws(() => avatar('data:image/png;base64,' + changed.toString('base64')), error => error.code === 'AVATAR_INVALID');
  assert.throws(() => avatar('data:image/png;base64,' + Buffer.concat([bytes, Buffer.from('private file')]).toString('base64')), error => error.code === 'AVATAR_INVALID');
});

test('profile photo update is persisted and hash-bound to new device certificate and Flash lookup', async t => {
  const f = setup(t), account = await register(f), caller = auth(f, account);
  const result = f.service.updateProfile(caller, {name: 'Новое имя', avatar: image});
  assert.equal(result.certificate.claims.avatarHash, avatar(image).avatarHash);
  f.service.flashPresence(caller, {});
  const found = f.service.flashDevices(caller, account.account.id);
  assert.equal(found.account.avatar, image); assert.equal(found.devices[0].certificate.claims.name, 'Новое имя');
  f.reopen(); assert.equal(f.service.me(auth(f, account)).account.avatar, image);
});
